using System.Security.Claims;using Microsoft.AspNetCore.Mvc;using Topstar.Application.Disputes;using Topstar.Application.Profiles;
namespace Topstar.Web.Pages.Brand;public sealed class DisputeDetailModel(IProfileAccessService access,IDisputeService service):BrandGuardedPageModel(access){[BindProperty(SupportsGet=true)]public Guid Id{get;set;}public DisputeCaseDetail? Detail{get;private set;}[TempData]public string? Message{get;set;}[TempData]public bool MessageSuccess{get;set;}public async Task<IActionResult> OnGetAsync(CancellationToken ct){var r=await RedirectIfProfileIncompleteAsync(false);if(r is not null)return r;Detail=await service.GetDetailAsync(UserId(),"BRAND",Id,ct);return Detail is null?NotFound():Page();}public async Task<IActionResult> OnPostMessageAsync(string body,string? evidenceUrl,CancellationToken ct){var x=await service.AddMessageAsync(UserId(),"BRAND",Id,body,evidenceUrl,false,ct);Message=x.Message;MessageSuccess=x.Success;return RedirectToPage(new{id=Id});}private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);}
